  var currentShown = 30;
  var totalProducts = 32;
  var isLoading = false;

  window.showNextProductBatch = function() {
    if (isLoading || currentShown >= totalProducts) return;
    isLoading = true;

    var hiddenCards = document.querySelectorAll('.product-card-extra');
    if (!hiddenCards || hiddenCards.length === 0) {
      finishAllProducts();
      return;
    }

    var toReveal = Array.from(hiddenCards).slice(0, 30);
    toReveal.forEach(function(card) {
      card.classList.remove('product-card-extra');
      card.style.display = '';
    });

    currentShown = totalProducts - document.querySelectorAll('.product-card-extra').length;

    var countText = document.getElementById('loaderCountText');
    if (countText) {
      countText.textContent = 'Loading more products (' + currentShown + ' of ' + totalProducts + ')...';
    }

    if (typeof initLiveTimer === 'function') {
      initLiveTimer();
    }

    setTimeout(function() {
      isLoading = false;
      if (document.querySelectorAll('.product-card-extra').length === 0) {
        finishAllProducts();
      }
    }, 120);
  };

  function finishAllProducts() {
    var loader = document.getElementById('productLoader');
    if (loader) {
      loader.innerHTML = '<div style="text-align: center; padding: 24px 0 10px; color: #8b8ba3; font-size: 13px; font-weight: 600;">🎉 You have viewed all ' + totalProducts + ' products!</div>';
    }
  }

  // Setup click on loader
  var loaderEl = document.getElementById('productLoader');
  if (loaderEl) {
    loaderEl.style.cursor = 'pointer';
    loaderEl.onclick = function() {
      window.showNextProductBatch();
    };
  }

  // Setup scroll listener
  window.addEventListener('scroll', function() {
    var scrollPos = window.innerHeight + (window.pageYOffset || document.documentElement.scrollTop);
    var threshold = document.documentElement.scrollHeight - 650;
    if (scrollPos >= threshold) {
      window.showNextProductBatch();
    }
  }, { passive: true });

  // Setup IntersectionObserver
  if ('IntersectionObserver' in window && loaderEl) {
    var observer = new IntersectionObserver(function(entries) {
      if (entries[0].isIntersecting) {
        window.showNextProductBatch();
      }
    }, { rootMargin: '450px' });
    observer.observe(loaderEl);
  }
})();

// Fail-safe buyNow if main.js is delayed
if (typeof window.buyNow !== 'function') {
  window.buyNow = function(id) {
    try {
      var prod = (window.allProducts || []).find(function(p) { return p.id == id; });
      var cart = JSON.parse(localStorage.getItem('meesho_cart_v1') || '[]');
      if (prod && !cart.some(function(i) { return i.id == id; })) {
        cart.push(Object.assign({}, prod, { qty: 1 }));
        localStorage.setItem('meesho_cart_v1', JSON.stringify(cart));
      }
    } catch(e) {}
    window.location.href = 'checkout.php?id=' + encodeURIComponent(id);
  };
}
</script>

