      <div class="drawer__title">
        <h3 class="ui2-heading">
          <span><b>Your Cart</b></span>
        </h3>
        <button type="button" class="closebtn" onclick="closeCartDrawer()" title="Close Cart">&times;</button>
      </div>
    </div>

    <!-- Container where JS populates cart products -->
    <div id="cartDrawerBody" class="cart-products-list">
      <!-- Empty state / loaded items rendered by main.js -->
    </div>

    <!-- Sticky Cart Drawer Footer -->
    <div id="cartDrawerFooter" class="cart__footer" style="display: none;">
      <div class="cart__price__details">
        <div class="cart__breakup__inner">
          <div class="shipping__total">
            <span>Shipping:</span>
            <span class="free-shipping-tag">FREE</span>
          </div>
          <div class="cart__total">
